(()=>{'use strict';const $=s=>document.querySelector(s);const key='embodied-wiki-read-v1';let read=[];try{read=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(read))read=[]}catch{}const page=document.body.dataset.page;
function update(){const done=read.includes(page);$('#mark-read').textContent=done?'✓ 本页已读':'○ 标记本页已读';$('#mark-read').setAttribute('aria-pressed',String(done));const count=[...document.querySelectorAll('[data-page].read-dot')].filter(e=>{e.classList.toggle('done',read.includes(e.dataset.page));return read.includes(e.dataset.page)}).length;$('#progress').value=count;$('#progress-text').textContent=`${count} / 9`;try{localStorage.setItem(key,JSON.stringify(read))}catch{}}
$('#mark-read').onclick=()=>{read=read.includes(page)?read.filter(p=>p!==page):[...read,page];update()};$('#reset-progress').onclick=()=>{if(confirm('重置当前浏览器的阅读进度？不会影响作业记录。')){read=[];update()}};update();
function menu(open){document.body.classList.toggle('menu-open',open);$('#menu-toggle').setAttribute('aria-expanded',String(open))}$('#menu-toggle').onclick=()=>menu(!document.body.classList.contains('menu-open'));$('#scrim').onclick=()=>menu(false);
for(const pre of document.querySelectorAll('pre')){const btn=document.createElement('button');btn.className='copy-code';btn.textContent='复制';btn.onclick=async()=>{try{await navigator.clipboard.writeText(pre.querySelector('code')?.textContent||'');btn.textContent='已复制'}catch{btn.textContent='请手动选择复制'}setTimeout(()=>btn.textContent='复制',1800)};pre.append(btn)}
let index=null;const dialog=$('#search-dialog');async function openSearch(){dialog.showModal();$('#search-input').focus();if(!index){try{const r=await fetch('search-index.json');if(!r.ok)throw Error();index=await r.json();runSearch()}catch{$('#search-status').textContent='搜索索引加载失败，请刷新页面或使用左侧目录。'}}}$('#search-open').onclick=openSearch;$('#search-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog&&e.clientX<dialog.getBoundingClientRect().left)dialog.close()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();if(!dialog.open)openSearch()}if(e.key==='Escape')menu(false)});
function runSearch(){const q=$('#search-input').value.trim().toLowerCase(),box=$('#search-results');box.replaceChildren();if(!q){$('#search-status').textContent='输入关键词，查找课程中的内容。';return}if(!index){$('#search-status').textContent='正在加载索引…';return}const terms=q.split(/\s+/);const matches=index.filter(p=>terms.every(t=>(p.title+' '+p.text).toLowerCase().includes(t)));$('#search-status').textContent=`找到 ${matches.length} 个相关页面`;for(const item of matches){const a=document.createElement('a');a.href=item.url;const strong=document.createElement('strong');strong.textContent=item.title;const p=document.createElement('p');const pos=Math.max(0,item.text.toLowerCase().indexOf(terms[0]));p.textContent=(pos>40?'…':'')+item.text.slice(Math.max(0,pos-40),pos+160)+'…';a.append(strong,p);box.append(a)}}$('#search-input').addEventListener('input',runSearch);
})();
